import {PUSH_SERVER} from './push-config.js';
import {PushClient,validatePushOptions,PUSH_KEY,pushSchedule,PUSH_ITEMS_KEY,loadItemPush,validateItemPush} from './push.js';
import {PRIORITIES,activeAreas} from './domain.js';
import {submitOnce,checkForm} from './forms.js';
export function createPushUI({storage,getState,getPreferences,target,esc,icon,toast,openModal,closeModal,onChange}){
  const client=new PushClient({storage,getState,getPreferences,target,server:PUSH_SERVER,onChange});let timer,busy=false,itemsRaw,itemsCache={};
  function itemOptions(){const raw=storage.getItem(PUSH_ITEMS_KEY);if(raw!==itemsRaw){const next=loadItemPush({getItem:()=>raw});itemsRaw=raw;itemsCache=next}return itemsCache}
  const check=(id,text,value)=>`<label class="planning-check" for="${id}"><input type="checkbox" id="${id}" ${value?'checked':''}><span>${esc(text)}</span></label>`;
  const time=(id,label,value)=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="time" required step="60" value="${esc(value)}"></div>`;
  const leadOptions=current=>[[0,'Na hora'],[5,'5 minutos'],[15,'15 minutos'],[30,'30 minutos'],[60,'1 hora'],[180,'3 horas'],[1440,'1 dia']].map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('');
  function status(){if(!PUSH_SERVER)return 'Servidor ainda não ativado';if(client.error)return 'Atualização pendente';if(client.active)return 'Confirmado pelo servidor';if(client.data?.token)return 'Ativação pendente';return 'Desativado neste aparelho'}
  function preview(o=client.options()){
    let entries;try{entries=pushSchedule(getState(),getPreferences(),o,Date.now(),loadItemPush(storage))}catch(error){return `<p class="planning-warning">${esc(error.message)}</p>`}
    const date=new Intl.DateTimeFormat('pt-BR',{timeZone:getPreferences().timeZone,dateStyle:'short',timeStyle:'short'});
    return `<div class="push-preview"><h3>Prévia dos próximos avisos</h3><p class="field-help">${entries.length} ${entries.length===1?'aviso calculado':'avisos calculados'}. Esta prévia não confirma o envio.</p>${entries.length?`<ul>${entries.slice(0,3).map(e=>`<li><strong>${esc(e.title)}</strong><span>${esc(date.format(e.at))}</span></li>`).join('')}</ul>`:'<p class="field-help">Nenhum prazo futuro corresponde às opções escolhidas.</p>'}</div>`;
  }
  function settings(){const configured=!!client.data?.options;return `<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('bell')}</span><div><h2>Notificações com o app fechado</h2><p role="status">${status()}</p></div></div><p>${!PUSH_SERVER?'Você pode personalizar e salvar as opções agora. O envio com o app fechado aguarda a ativação do servidor. Os lembretes no sino continuam disponíveis.':'Ao ativar, os títulos permitidos pelas suas opções, os prazos e a assinatura do aparelho serão enviados ao serviço. Observações e token de sincronização não são enviados.'}</p>${client.error?`<p role="status" class="planning-warning">${esc(client.error)}</p>`:''}<div class="settings-buttons push-buttons"><button class="btn secondary" data-action="planning-push-settings">Personalizar notificações</button><button class="btn secondary" data-action="planning-push-enable" ${!PUSH_SERVER||busy?'disabled':''}>${client.active?'Revalidar conexão':'Ativar neste aparelho'}</button>${client.data?.token?`<button class="btn secondary" data-action="planning-push-test" ${!client.active||busy?'disabled':''}>Enviar teste</button><button class="btn secondary" data-action="planning-push-disable" ${busy?'disabled':''}>Desativar neste aparelho</button>`:''}</div><p class="field-help">${configured?'Preferências salvas neste aparelho.':'Use Personalizar para escolher quando e quais avisos receber fora do app.'} Silêncio, som e permanência também dependem das permissões e configurações do Android e do navegador.</p><details class="settings-details"><summary>Ver prévia dos avisos calculados</summary>${preview()}</details></section>`}
  function itemButton(t){let o;try{o=itemOptions()[t.id]}catch{};return `<button type="button" class="item-push-button" data-action="planning-push-item" data-id="${esc(t.id)}" aria-label="Notificações de ${esc(t.title)}" title="${o?.mode==='off'?'Notificações silenciadas':o?.mode==='custom'?'Antecedência personalizada':'Notificações desta tarefa'}">${icon('bell')}${o&&o.mode!=='default'?'<span class="item-push-marker" aria-hidden="true">'+(o.mode==='off'?'−':'•')+'</span>':''}</button>`}
  function itemSettings(id){
    const t=getState().items[id];if(!t||t.deleted)throw Error('Esta tarefa não está disponível.');
    const all=loadItemPush(storage),current=all[id]||{mode:'default'},root=openModal('Notificações desta tarefa',`<form id="item-push-form"><div class="formerror" role="alert" tabindex="-1"></div><p class="confirmtext">${esc(t.title)}</p><div class="field"><label for="item-push-mode">Como avisar neste aparelho</label><select data-full-value id="item-push-mode">${[['default','Seguir as configurações gerais'],['off','Silenciar notificações push'],['custom','Usar outra antecedência']].map(([v,l])=>`<option value="${v}" ${current.mode===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="item-push-minutes">Antecedência desta tarefa</label><select id="item-push-minutes">${leadOptions(current.minutes??client.options().priorityMinutes[t.priority])}</select></div><p class="field-help">O ajuste vale apenas para esta tarefa e neste aparelho. Os subitens têm suas próprias opções. Silenciar push mantém os lembretes no sino. Uma antecedência própria substitui os avisos gerais desta tarefa; filtros, privacidade e período silencioso continuam valendo.${!t.date?' Defina uma data para esta tarefa gerar avisos.':''}</p><p class="field-help">${!PUSH_SERVER?'O servidor ainda não foi ativado. Salvar esta opção não ativa o envio.':'As alterações precisam ser confirmadas pelo servidor.'}</p><div class="dialogactions"><button type="button" class="btn secondary" id="item-push-cancel">Cancelar</button><button type="submit" class="btn primary">Salvar opção</button></div></form>`);
    const mode=root.querySelector('#item-push-mode'),minutes=root.querySelector('#item-push-minutes');const update=()=>minutes.disabled=mode.value!=='custom';mode.onchange=update;update();root.querySelector('#item-push-cancel').onclick=()=>closeModal();
    root.querySelector('form').onsubmit=submitOnce(async e=>{try{if(!checkForm(e.target))return;const next=loadItemPush(storage),value=validateItemPush({mode:mode.value,minutes:Number(minutes.value)});if(value.mode==='default')delete next[id];else next[id]=value;const raw=JSON.stringify(next);storage.setItem(PUSH_ITEMS_KEY,raw);if(storage.getItem(PUSH_ITEMS_KEY)!==raw)throw Error('Não foi possível salvar neste aparelho.');await client.sync();closeModal(true);onChange();toast(client.error?'Opção salva neste aparelho; o envio ao servidor está pendente.':'Opção de notificação salva neste aparelho.')}catch(error){const field=root.querySelector('.formerror');field.textContent=error.message;field.focus()}});
  }
  async function action(name,data={}){
    if(name==='planning-push-item'){itemSettings(data.id);return}

    if(name!=='planning-push-settings'){
      if(busy)return;busy=true;
      try{if(name==='planning-push-disable'){await client.disable();toast('Notificações desativadas neste aparelho.')}else if(name==='planning-push-test'){await client.test();toast('Teste aceito pelo serviço. Confira a notificação no celular.')}else if(name==='planning-push-enable'){await client.enable(client.options());toast('Agendamento confirmado pelo servidor.')}}finally{busy=false;onChange()}
      return;
    }
    const o=client.options(),areas=activeAreas(getState()),root=openModal('Personalizar notificações',`<form id="push-settings-form"><div class="formerror" role="alert" tabindex="-1"></div><p class="settings-intro">Estas opções são para notificações do celular com o app fechado. Salvar preferências não ativa o serviço.</p><details class="settings-details"><summary>Quais tarefas avisar</summary><fieldset class="push-fieldset"><legend>Filtros</legend>${check('push-items','Itens principais',o.includeItems)}${check('push-subitems','Subitens',o.includeSubitems)}<div class="push-priorities">${PRIORITIES.map(p=>`<div class="push-priority">${check('push-priority-'+p.id,p.label,o.priorities.includes(p.id))}<div class="field"><label for="push-lead-${p.id}">Antecedência · ${p.label}</label><select id="push-lead-${p.id}">${leadOptions(o.priorityMinutes[p.id])}</select></div></div>`).join('')}</div><details class="settings-details"><summary>Filtrar áreas</summary>${check('push-all-areas','Todas as áreas, incluindo novas áreas',!o.areas.length)}<div class="push-areas">${areas.map((a,i)=>check('push-area-'+i,a.name,!o.areas.length||o.areas.includes(a.id))).join('')}</div><p class="field-help">Com todas as áreas selecionadas, áreas criadas depois também serão incluídas.</p></details></fieldset></details><fieldset class="push-fieldset"><legend>Quando avisar</legend><div class="field"><label for="push-common-lead">Antecedência padrão</label><select id="push-common-lead">${leadOptions(o.minutes)}</select><small class="field-help" id="push-common-hint">Ao alterar, este valor passa a valer para todas as prioridades. Exceções por prioridade ficam em Quais tarefas avisar; ajustes por tarefa ficam em Gerenciar → Notificações.</small></div>${time('push-time','Horário para tarefas sem horário',o.defaultTime)}${check('push-at-deadline','Avisar também na hora do prazo',o.atDeadline)}<details class="settings-details"><summary>Período silencioso</summary>${check('push-quiet','Usar período silencioso',o.quietEnabled)}<div class="fieldsrow">${time('push-quiet-start','Silêncio a partir de',o.quietStart)}${time('push-quiet-end','Retomar avisos às',o.quietEnd)}</div><p class="field-help">Durante o período silencioso, os avisos aguardam o horário de retomada, mesmo que isso ocorra depois do prazo. Avisos do mesmo item que coincidirem nesse horário serão reunidos. Fuso: ${esc(getPreferences().timeZone)}.</p></details></fieldset><details class="settings-details"><summary>Privacidade e apresentação</summary><fieldset class="push-fieldset"><legend>Conteúdo e apresentação</legend>${check('push-private','Ocultar o título da tarefa na notificação',o.private)}${check('push-silent','Pedir notificações sem som e vibração',o.silent)}${check('push-sticky','Pedir que o aviso permaneça até ser dispensado',o.sticky)}<p class="field-help">O Android e o navegador podem não atender às opções de som e permanência. Ao ocultar o título, o servidor recebe apenas uma mensagem genérica.</p></fieldset></details><div id="push-options-preview" aria-live="polite">${preview(o)}</div><div class="dialogactions"><button class="btn secondary" type="button" id="push-cancel">Cancelar</button><button class="btn primary" type="submit">Salvar preferências</button></div></form>`);
    const node=id=>root.querySelector('#'+id),checked=id=>node(id).checked;
    function read(){return validatePushOptions({...o,minutes:Number(node('push-common-lead').value),defaultTime:node('push-time').value,priorities:PRIORITIES.filter(p=>checked('push-priority-'+p.id)).map(p=>p.id),priorityMinutes:Object.fromEntries(PRIORITIES.map(p=>[p.id,Number(node('push-lead-'+p.id).value)])),includeItems:checked('push-items'),includeSubitems:checked('push-subitems'),areas:checked('push-all-areas')?[]:areas.filter((a,i)=>checked('push-area-'+i)).map(a=>a.id),atDeadline:checked('push-at-deadline'),quietEnabled:checked('push-quiet'),quietStart:node('push-quiet-start').value,quietEnd:node('push-quiet-end').value,private:checked('push-private'),silent:checked('push-silent'),sticky:checked('push-sticky')})}
    const update=()=>{
      node('push-common-hint').textContent=PRIORITIES.some(p=>node('push-lead-'+p.id).value!==node('push-common-lead').value)?'Há antecedências personalizadas por prioridade em Quais tarefas avisar. Alterar o padrão substitui esses ajustes.':'Ao alterar, este valor passa a valer para todas as prioridades. Exceções por prioridade ficam em Quais tarefas avisar; ajustes por tarefa ficam em Gerenciar → Notificações.';
      for(const p of PRIORITIES)node('push-lead-'+p.id).disabled=!checked('push-priority-'+p.id);
      for(const id of ['push-quiet-start','push-quiet-end'])node(id).disabled=!checked('push-quiet');
      areas.forEach((a,i)=>node('push-area-'+i).disabled=checked('push-all-areas'));
      try{const next=read();if(!checked('push-all-areas')&&!next.areas.length)throw Error('Selecione pelo menos uma área ou marque Todas as áreas.');node('push-options-preview').innerHTML=preview(next)}catch(error){node('push-options-preview').innerHTML=`<p class="planning-warning">${esc(error.message)}</p>`}
    };
    node('push-common-lead').addEventListener('change',()=>{for(const p of PRIORITIES)node('push-lead-'+p.id).value=node('push-common-lead').value});
    root.querySelector('form').addEventListener('change',update);update();
    node('push-cancel').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{try{
      if(!checkForm(e.target))return;const next=read();if(!checked('push-all-areas')&&!next.areas.length)throw Error('Selecione pelo menos uma área ou marque Todas as áreas.');
      await client.saveOptions(next);closeModal(true);toast(client.active?'Preferências salvas e fila atualizada.':'Preferências salvas neste aparelho. O envio continua desativado.');
    }catch(error){const field=root.querySelector('.formerror');field.textContent=error.message;field.focus();field.scrollIntoView({block:'nearest'})}});
  }
  const reload=e=>{if(e.key===PUSH_ITEMS_KEY){client.fingerprint='';client.sync();onChange();return}if(e.key===PUSH_KEY){try{client.data=JSON.parse(storage.getItem(PUSH_KEY)||'null');client.fingerprint='';client.sync();onChange()}catch{}}};
  return {settings,action,itemButton,sync:()=>client.sync(),start(){client.sync();timer=target.setInterval(()=>client.sync(),60000);target.addEventListener('storage',reload)},dispose(){target.clearInterval(timer);target.removeEventListener('storage',reload)}};
}
